                            error.CallTimedOut
                        else
                            error.RemoteException,
                        // .failed, .unimplemented (spec: treat like failed), and
                        // any future code. `else` is required: the enum is
                        // non-exhaustive because the wire field is remote-controlled.
                        else => error.RemoteException,
                    },
                    .canceled => error.Canceled,
                    .results_sent_elsewhere, .take_from_other_question, .accept_from_third_party => error.UnexpectedReturn,
                };
            }
        };
        pub const Callback = *const fn (ctx: *anyopaque, peer: *rpc.peer.Peer, response: Response, caps: *const rpc.caps.table.InboundCapTable) anyerror!void;

        const CallContext = struct {
            user_ctx: *anyopaque,
            build: ?BuildFn,
            callback: Callback,

            // While a generated send is still on the caller's stack, this
            // points at its ownership flag. A synchronous Return marks the
            // context settled before freeing it; an asynchronous send clears
            // the pointer before returning to the user.
            settled_flag: ?*bool = null,

            // Frees the heap ctx if the question is still outstanding at
            // Peer.deinit (the normal return path frees it in callReturn).
            fn deinitCtx(ctx_allocator: std.mem.Allocator, ctx_ptr: *anyopaque) void {
                const dead: *CallContext = @ptrCast(@alignCast(ctx_ptr));
                ctx_allocator.destroy(dead);
            }
        };

        const DirectReturnContext = struct {
            handler: Handler,
            ctx: *anyopaque,
            peer: *rpc.peer.Peer,
            params: Params.Reader,
            caps: *const rpc.caps.table.InboundCapTable,
        };

        pub const ReturnSender = struct {
            peer: *rpc.peer.Peer,
            question_id: u32,

            pub fn sendResults(self: ReturnSender, ctx: *anyopaque, build: *const fn (ctx: *anyopaque, ret: *rpc.wire.protocol.ReturnBuilder) anyerror!void) !void {
                try self.peer.sendReturnResults(self.question_id, ctx, build);
            }

            pub fn sendException(self: ReturnSender, reason: []const u8) !void {
                try self.peer.sendReturnException(self.question_id, reason);
            }
        };

        fn callBuild(ctx_ptr: *anyopaque, call: *rpc.wire.protocol.CallBuilder) anyerror!void {
            const ctx: *CallContext = @ptrCast(@alignCast(ctx_ptr));
            var payload = try call.payloadTyped();
            var params_any = try payload.initContent();
            const params_builder = try params_any.initStruct(0, 0);
            var params = Params.Builder.wrap(params_builder);
            if (ctx.build) |build_fn| {
                try build_fn(ctx.user_ctx, &params);
            }
            _ = try call.initCapTableTyped(0);
        }

        fn callReturn(ctx_ptr: *anyopaque, peer: *rpc.peer.Peer, ret: rpc.wire.protocol.Return, caps: *const rpc.caps.table.InboundCapTable) anyerror!void {
            const ctx: *CallContext = @ptrCast(@alignCast(ctx_ptr));
            if (ctx.settled_flag) |flag| flag.* = true;
            defer peer.allocator.destroy(ctx);
            var response: Response = undefined;
            switch (ret.tag) {
                .results => {
                    const payload = ret.results orelse return error.MissingReturnPayload;
                    const struct_reader = try payload.content.getStruct();
                    const results = Results.Reader.wrap(struct_reader);
                    response = .{ .results = results };
                },
                .exception => {
                    const ex = ret.exception orelse return error.MissingException;
                    response = .{ .exception = ex };
                },
                .canceled => response = .canceled,
                .resultsSentElsewhere => response = .results_sent_elsewhere,
                .takeFromOtherQuestion => {
                    const qid = ret.take_from_other_question orelse return error.MissingQuestionId;
                    response = .{ .take_from_other_question = qid };
                },
                .awaitFromThirdParty => response = .accept_from_third_party,
            }
            try ctx.callback(ctx.user_ctx, peer, response, caps);
        }

        pub fn handleCallDirect(handler: Handler, deferred_handler: ?DeferredHandler, ctx: *anyopaque, peer: *rpc.peer.Peer, call: rpc.wire.protocol.Call, caps: *const rpc.caps.table.InboundCapTable) anyerror!void {
            const params_struct = try call.params.content.getStruct();
            const params = Params.Reader.wrap(params_struct);
            if (deferred_handler) |deferred_fn| {
                const sender = ReturnSender{ .peer = peer, .question_id = call.question_id };
                try deferred_fn(ctx, peer, params, caps, sender);
            } else {
                var dctx = DirectReturnContext{
                    .handler = handler,
                    .ctx = ctx,
                    .peer = peer,
                    .params = params,
                    .caps = caps,
                };
                try peer.sendReturnResults(call.question_id, &dctx, buildReturnDirect);
            }
        }

        fn handleCall(server: *Server, peer: *rpc.peer.Peer, call: rpc.wire.protocol.Call, caps: *const rpc.caps.table.InboundCapTable) anyerror!void {
            try handleCallDirect(server.vtable.ping, server.vtable.ping_deferred, server.ctx, peer, call, caps);
        }

        fn buildReturnDirect(ctx_ptr: *anyopaque, ret: *rpc.wire.protocol.ReturnBuilder) anyerror!void {
            const dctx: *DirectReturnContext = @ptrCast(@alignCast(ctx_ptr));
            var payload = try ret.payloadTyped();
            var results_any = try payload.initContent();
            const results_builder = try results_any.initStruct(0, 0);
            var results = Results.Builder.wrap(results_builder);
            try dctx.handler(dctx.ctx, dctx.peer, dctx.params, &results, dctx.caps);
        }
    };

    pub const Client = struct {
        peer: *rpc.peer.Peer,
        cap_id: u32,

        pub fn init(peer: *rpc.peer.Peer, cap_id: u32) Client {
            return .{ .peer = peer, .cap_id = cap_id };
        }

        /// Release the import ref this Client owns (balances the bootstrap-return
        /// retainCapability). Call at most once per owned Client; best-effort —
        /// peer teardown's import release is the backstop.
        pub fn release(self: Client) void {
            self.peer.releaseImport(self.cap_id, 1) catch {};
        }

        pub fn callPing(self: Client, user_ctx: *anyopaque, build: ?Ping.BuildFn, on_return: Ping.Callback) !u32 {
            return self.callPingWithOptions(user_ctx, build, on_return, .{});
        }

        pub fn callPingWithOptions(self: Client, user_ctx: *anyopaque, build: ?Ping.BuildFn, on_return: Ping.Callback, options: rpc.peer.CallOptions) !u32 {
            const ctx = try self.peer.allocator.create(Ping.CallContext);
            var settled = false;
            ctx.* = .{ .user_ctx = user_ctx, .build = build, .callback = on_return, .settled_flag = &settled };
            const question_id = self.peer.sendCallGeneratedWithOptions(self.cap_id, interface_id, Ping.ordinal, ctx, Ping.callBuild, Ping.callReturn, options) catch |err| {
                if (!settled) self.peer.allocator.destroy(ctx);
                return err;
            };
            if (settled) return question_id;
            ctx.settled_flag = null;
            self.peer.setQuestionDeinitCtx(question_id, Ping.CallContext.deinitCtx);
            return question_id;
        }

        pub fn fromBootstrap(peer: *rpc.peer.Peer, user_ctx: *anyopaque, callback: BootstrapCallback) !u32 {
            return bootstrap(peer, user_ctx, callback);
        }
    };

    pub const PipelinedClient = struct {
        peer: *rpc.peer.Peer,
        question_id: u32,
        pointer_index: u16,

        pub fn callPing(self: PipelinedClient, user_ctx: *anyopaque, build: ?Ping.BuildFn, on_return: Ping.Callback) !u32 {
            return self.callPingWithOptions(user_ctx, build, on_return, .{});
        }

        pub fn callPingWithOptions(self: PipelinedClient, user_ctx: *anyopaque, build: ?Ping.BuildFn, on_return: Ping.Callback, options: rpc.peer.CallOptions) !u32 {
            const ctx = try self.peer.allocator.create(Ping.CallContext);
            var settled = false;
            ctx.* = .{ .user_ctx = user_ctx, .build = build, .callback = on_return, .settled_flag = &settled };
            const question_id = self.peer.sendCallPromisedWithOpsGeneratedWithOptions(self.question_id, &[_]rpc.wire.protocol.PromisedAnswerOp{.{ .tag = .getPointerField, .pointer_index = self.pointer_index }}, interface_id, Ping.ordinal, ctx, Ping.callBuild, Ping.callReturn, options) catch |err| {
                if (!settled) self.peer.allocator.destroy(ctx);
                return err;
            };
            if (settled) return question_id;
            ctx.settled_flag = null;
            self.peer.setQuestionDeinitCtx(question_id, Ping.CallContext.deinitCtx);
            return question_id;
        }
    };

    pub const BootstrapResponse = union(enum) {
        client: Client,
        exception: rpc.wire.protocol.Exception,
        canceled,
        results_sent_elsewhere,
        take_from_other_question: u32,
        accept_from_third_party,

        /// Collapse this BootstrapResponse into its Client or a typed
        /// rpc.peer.CallError. Classification comes from the exception's
        /// spec `Exception.Type`, so a disconnect reported by ANY
        /// implementation is recognized; every other exception is
        /// RemoteException (reason available on the union arm).
        pub fn unwrap(self: BootstrapResponse) rpc.peer.CallError!Client {
            return switch (self) {
                .client => |c| c,
                .exception => |ex| switch (ex.kind()) {
                    .disconnected => error.Disconnected,
                    // The spec has no distinct timeout type and classes
                    // timeouts as overloaded, so our own deadline sentinel
                    // still separates a local timeout from a remote's
                    // genuine backpressure.
                    .overloaded => if (std.mem.eql(u8, ex.reason, rpc.peer.deadline_reason))
                        error.CallTimedOut
                    else
                        error.RemoteException,
                    // .failed, .unimplemented (spec: treat like failed), and
                    // any future code. `else` is required: the enum is
                    // non-exhaustive because the wire field is remote-controlled.
                    else => error.RemoteException,
                },
                .canceled => error.Canceled,
                .results_sent_elsewhere, .take_from_other_question, .accept_from_third_party => error.UnexpectedReturn,
            };
        }
    };
    pub const BootstrapCallback = *const fn (ctx: *anyopaque, peer: *rpc.peer.Peer, response: BootstrapResponse) anyerror!void;

    const BootstrapContext = struct {
        user_ctx: *anyopaque,
        callback: BootstrapCallback,

        fn deinitCtx(ctx_allocator: std.mem.Allocator, ctx_ptr: *anyopaque) void {
            const dead: *BootstrapContext = @ptrCast(@alignCast(ctx_ptr));
            ctx_allocator.destroy(dead);
        }
    };

    fn bootstrapReturn(ctx_ptr: *anyopaque, peer: *rpc.peer.Peer, ret: rpc.wire.protocol.Return, caps: *const rpc.caps.table.InboundCapTable) anyerror!void {
        const ctx: *BootstrapContext = @ptrCast(@alignCast(ctx_ptr));
        defer peer.allocator.destroy(ctx);
        var response: BootstrapResponse = undefined;
        switch (ret.tag) {
            .results => {
                const payload = ret.results orelse return error.MissingReturnPayload;
                const cap = try payload.content.getCapability();
                var mutable_caps = caps.*;
                try mutable_caps.retainCapability(cap);
                const resolved = try caps.resolveCapability(cap);
                switch (resolved) {
                    .imported => |imported| response = .{ .client = Client.init(peer, imported.id) },
                    else => return error.UnexpectedBootstrapCapability,
                }
            },
            .exception => {
                const ex = ret.exception orelse return error.MissingException;
                response = .{ .exception = ex };
            },
            .canceled => response = .canceled,
            .resultsSentElsewhere => response = .results_sent_elsewhere,
            .takeFromOtherQuestion => {
                const qid = ret.take_from_other_question orelse return error.MissingQuestionId;
                response = .{ .take_from_other_question = qid };
            },
            .awaitFromThirdParty => response = .accept_from_third_party,
        }
        try ctx.callback(ctx.user_ctx, peer, response);
    }

    pub fn bootstrap(peer: *rpc.peer.Peer, user_ctx: *anyopaque, callback: BootstrapCallback) !u32 {
        const ctx = try peer.allocator.create(BootstrapContext);
        errdefer peer.allocator.destroy(ctx);
        ctx.* = .{ .user_ctx = user_ctx, .callback = callback };
        const question_id = try peer.sendBootstrap(ctx, bootstrapReturn);
        peer.setQuestionDeinitCtx(question_id, BootstrapContext.deinitCtx);
        return question_id;
    }

